import type { Logger } from "../utils/logger";
import { buildExceptionPayload } from "./exceptionBuilder";
import type { TimeProvider } from "../utils/timeProvider";
import type { ISignalProcessor } from "../events/signalProcessor";

interface Options {
  onerror?: boolean;
  onunhandledrejection?: boolean;
  patchGlobalPromise?: boolean;
  timeProvider: TimeProvider;
  logger: Logger;
  signalProcessor: ISignalProcessor;
}

const DEFAULTS: Omit<Required<Options>, "timeProvider" | "logger" | "signalProcessor"> = {
  onerror: true,
  onunhandledrejection: true,
  patchGlobalPromise: true,
};

let defaultErrorHandler: ((error: any, isFatal?: boolean) => void) | undefined;

/**
 * Initialize React Native global crash & exception tracking
 */
export function setupErrorHandlers(options: Options): void {
  const { timeProvider, logger, signalProcessor, ...rest } = options;
  const merged = { ...DEFAULTS, ...rest };
  const log: Logger = logger

  if (merged.onerror) {
    setupGlobalErrorHandler(timeProvider, log, signalProcessor);
  }

  if (merged.onunhandledrejection) {
    setupUnhandledRejectionHandler(merged.patchGlobalPromise, timeProvider, log, signalProcessor);
  }
}

/**
 * Common function to capture, log and forward exceptions
 */
async function captureException(error: unknown, isFatal: boolean, timeProvider: TimeProvider, logger: Logger, signalProcessor: ISignalProcessor): Promise<void> {
  try {
    const severity = isFatal ? 'fatal' : 'unhandled';
    const exceptionPayload = buildExceptionPayload(error, severity);

    logger.log(
      isFatal ? "fatal" : "error",
      isFatal ? "Fatal exception" : "Exception",
      error,
      exceptionPayload
    );
    logger.log('debug', '[SignalProcessor] Exception data: ' + JSON.stringify(exceptionPayload), null, null);

    await signalProcessor.trackEvent(
      exceptionPayload,
      "exception",
      timeProvider.now(),
    );
  } catch (e) {
    logger.log("error", "Failed to process exception", e);
  }
}

/**
 * Hook into React Native's global ErrorUtils handler
 */
function setupGlobalErrorHandler(timeProvider: TimeProvider, logger: Logger, signalProcessor: ISignalProcessor): void {
  const errorUtils = (global as any).ErrorUtils;
  if (!errorUtils?.getGlobalHandler || !errorUtils?.setGlobalHandler) {
    logger.log(
      "warning",
      "ErrorUtils not found. Skipping global error handler setup."
    );
    return;
  }

  defaultErrorHandler = errorUtils.getGlobalHandler();

  errorUtils.setGlobalHandler(async (error: any, isFatal?: boolean) => {

    if (isFatal === true) {
      await captureException(error, true, timeProvider, logger, signalProcessor);
    }

    if (defaultErrorHandler) {
      defaultErrorHandler(error, isFatal);
    }
  });

  logger.internalLog("info", "Global error handler installed.");
}

/**
 * Setup unhandled Promise rejection tracking
 */
function setupUnhandledRejectionHandler(
  patchGlobalPromise: boolean,
  timeProvider: TimeProvider,
  logger: Logger,
  signalProcessor: ISignalProcessor
): void {
  try {
    const hermes = (global as any).HermesInternal;

    if (hermes?.enablePromiseRejectionTracker && typeof hermes.hasPromise === "function" && hermes.hasPromise()) {
      hermes.enablePromiseRejectionTracker({
        allRejections: true,
        onUnhandled: (id: string, error: unknown) => {
          captureException(error, false, timeProvider, logger, signalProcessor);
        },
      });
      logger.internalLog("info", "Using Hermes promise rejection tracking.");
    } else if (patchGlobalPromise) {
      const rejectionTracking = require("promise/setimmediate/rejection-tracking");
      rejectionTracking.enable({
        allRejections: true,
        onUnhandled: (id: string, error: unknown) => {
          captureException(error, false, timeProvider, logger, signalProcessor);
        },
      });
      logger.internalLog("info", "Using polyfill for promise rejection tracking.");
    } else {
      logger.internalLog("warning", "Unhandled promise rejection tracking disabled.");
    }
  } catch (e) {
    logger.log("error", "Failed to set up promise rejection tracking", e);
  }
}